// Writes jobs/<feed>.md: the research, sourcing, verification and outlet-map instructions of jobs/legacy/<feed>.md
// (minus its HTML comment header and its old Markdown OUTPUT section), then the JSON contract generated by
// @news/schema. `--check` exits non-zero when a file is stale. `--out DIR` writes/checks another directory (tests).
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { FEED_IDS, promptSection, type FeedId } from "@news/schema";

const ROOT = join(import.meta.dir, "..");
const LEGACY_DIR = join(ROOT, "jobs", "legacy");

interface Rule {
  /** The old output section starts at the line beginning with this text... */
  cutFrom: string;
  /** ...and ends right before the line beginning with this text (or at the end of the file). */
  cutTo?: string;
  /** Exact replacements; each must match exactly once, so a changed legacy prompt fails loudly. */
  replace: [string, string][];
  /** Paragraphs appended to the kept instructions. */
  append?: string[];
}

const CONTINUITY_OLD =
  'Your previous output is provided via continuity. Do not repeat stories already covered unless there is a material new development, which you mark as "Update".';
const CONTINUITY_NEW =
  "Your previous edition (JSON) is provided via continuity. Do not repeat stories already covered unless there is a material new development, which you mark as an update (see CONTINUITY below).";

const RULES: Record<FeedId, Rule> = {
  chile: {
    cutFrom: "OUTPUT (",
    cutTo: "Coverage is a sample",
    replace: [
      [
        "You produce a daily Chilean news briefing delivered to Telegram, in the style of Ground News:",
        "You produce a daily Chilean news briefing for a personal news reader (a web app, plus a short notice in Telegram), in the style of Ground News:",
      ],
      [CONTINUITY_OLD, CONTINUITY_NEW],
      [
        "If the snapshot is missing or failed, say so in the coverage-gaps line and rely on web_search.",
        "If the snapshot is missing or failed, say so in `gaps` and rely on web_search.",
      ],
      [
        'must be labeled "reported only by <outlet>, unconfirmed".',
        'must be labeled "reported only by <outlet>, unconfirmed" in the summary, with `verification` set to `unverified`.',
      ],
    ],
  },
  cyber: {
    cutFrom: "OUTPUT (",
    cutTo: "Coverage is a sample",
    replace: [
      [
        "You produce a daily cybersecurity briefing delivered to Telegram for one technical reader:",
        "You produce a daily cybersecurity briefing for one technical reader, read in a personal news reader (a web app, plus a short notice in Telegram):",
      ],
      [CONTINUITY_OLD, CONTINUITY_NEW],
      ['READER\'S STACK (for the "Your stack" section):', "READER'S STACK (for the `your_stack` section):"],
      [
        "If the snapshot is missing or failed, say so in the coverage-gaps line and rely on web_search.",
        "If the snapshot is missing or failed, say so in `gaps` and rely on web_search.",
      ],
    ],
  },
  ai: {
    cutFrom: "Sections (skip empty ones):",
    replace: [
      [
        "Produce a weekly AI news digest covering the past 7 days (up to today).",
        "Produce a daily AI news digest for a personal news reader (a web app, plus a short notice in Telegram), covering the last ~24 hours (since the previous edition).",
      ],
      ["Only include items published in the last 7 days; verify dates.", "Only include items published in the last ~24 hours; verify dates."],
    ],
    append: [
      "Your previous edition (JSON) may be provided via continuity. Avoid repeating stories already covered unless there is a significant update, which you mark as an update (see CONTINUITY below).",
      "Keep the digest short: about 5-10 stories in total, one or two sentences each. On a quiet day fewer is fine. The old digest sections map onto the JSON sections: Top stories → `top`, Model & product releases → `release`, Open-source & local AI → `open_source`, Research highlights → `research`, Industry, funding & policy → `industry`.",
    ],
  },
};

function countOccurrences(haystack: string, needle: string): number {
  let n = 0;
  for (let i = haystack.indexOf(needle); i !== -1; i = haystack.indexOf(needle, i + needle.length)) n++;
  return n;
}

export function buildPrompt(feed: FeedId, legacy: string): string {
  const rule = RULES[feed];
  let text = legacy.replace(/\r\n/g, "\n").replace(/^\s*<!--[\s\S]*?-->\s*/, "");
  const lines = text.split("\n");
  const start = lines.findIndex((l) => l.startsWith(rule.cutFrom));
  if (start === -1) throw new Error(`${feed}: legacy prompt has no line starting with ${JSON.stringify(rule.cutFrom)}`);
  let end = lines.length;
  if (rule.cutTo) {
    end = lines.findIndex((l, i) => i > start && l.startsWith(rule.cutTo!));
    if (end === -1) throw new Error(`${feed}: legacy prompt has no line starting with ${JSON.stringify(rule.cutTo)}`);
  }
  text = [...lines.slice(0, start), ...lines.slice(end)].join("\n");
  for (const [from, to] of rule.replace) {
    const n = countOccurrences(text, from);
    if (n !== 1) throw new Error(`${feed}: expected exactly one ${JSON.stringify(from.slice(0, 60))}, found ${n}`);
    text = text.replace(from, () => to);
  }
  const paragraphs = text
    .split(/\n{2,}/)
    .map((p) => p.trim())
    .filter(Boolean);
  paragraphs.push(...(rule.append ?? []));
  return `${paragraphs.join("\n\n")}\n\n${promptSection(feed)}`;
}

function main(argv: string[]): number {
  const check = argv.includes("--check");
  const outIdx = argv.indexOf("--out");
  const outDir = outIdx !== -1 && argv[outIdx + 1] ? argv[outIdx + 1]! : join(ROOT, "jobs");
  const stale: string[] = [];
  for (const feed of FEED_IDS) {
    const prompt = buildPrompt(feed, readFileSync(join(LEGACY_DIR, `${feed}.md`), "utf8"));
    const file = join(outDir, `${feed}.md`);
    const current = existsSync(file) ? readFileSync(file, "utf8") : null;
    if (current === prompt) continue;
    if (check) {
      stale.push(file);
    } else {
      mkdirSync(outDir, { recursive: true });
      writeFileSync(file, prompt);
      console.log(`wrote ${file}`);
    }
  }
  if (check && stale.length) {
    console.error(`stale job prompts (run \`bun run gen:prompts\`):\n${stale.map((s) => `  ${s}`).join("\n")}`);
    return 1;
  }
  if (check) console.log("job prompts are up to date");
  return 0;
}

if (import.meta.main) process.exit(main(Bun.argv.slice(2)));
